  [&lt;a href=&quot;https://eprints.bbk.ac.uk/id/document/216935&quot; style=&quot;color:goldenrod&quot;&gt;Download&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;anitem genericitem&quot;&gt;&lt;span class=&quot;prefix&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;bibitem&quot;&gt;  &lt;a href=&quot;https://eprints.bbk.ac.uk/id/eprint/41119&quot; class=&quot;csl-entry&quot;&gt;Eve, Martin Paul, ‘The Open-Access Monograph Conundrum Can Be Solved’, &lt;i&gt;Times Higher Education&lt;/i&gt;, 2020&lt;/a&gt;
