ence&lt;/span&gt;&lt;/a&gt;&amp;rdquo;, &lt;i&gt;&lt;span itemscope=&quot;&quot; itemtype=&quot;http://schema.org/Periodical&quot;&gt;&lt;span id=&quot;name&quot;&gt;Palgrave Communications&lt;/span&gt;&lt;/span&gt;&lt;/i&gt; (3), &lt;span itemprop=&quot;datepublished&quot;&gt;2017&lt;/span&gt;&lt;/span&gt; [&lt;a href=&quot;http://eprints.bbk.ac.uk/id/document/32271&quot; style=&quot;color:goldenrod&quot;&gt;Download&lt;/a&gt;] &lt;/li&gt;
&lt;/ul&gt;

&lt;h4&gt;Book Chapters&lt;/h4&gt;
