&lt;td style=&quot;text-align:center;&quot;&gt;£3,555,000&lt;/td&gt;
&lt;/tr&gt;&lt;tr&gt;&lt;td style=&quot;text-align:left;&quot;&gt;London South Bank University&lt;/td&gt;
