&lt;td style=&quot;text-align:center;&quot;&gt;−9.5&lt;/td&gt;
&lt;td style=&quot;text-align:center;&quot;&gt;£2,700,000&lt;/td&gt;
&lt;/tr&gt;&lt;tr&gt;&lt;td style=&quot;text-align:left;&quot;&gt;Plymouth University&lt;/td&gt;
&lt;td class=&quot;xl63&quot; style=&quot;text-align:center;&quot;&gt;4,815&lt;/td&gt;
&lt;td class=&quot;xl63&quot; style=&quot;text-align:center;&quot;&gt;5,310&lt;/td&gt;
&lt;td style=&quot;text-align:center;&quot;&gt;−9.3&lt;/td&gt;
&lt;td style=&quot;text-align:center;&quot;&gt;£4,455,000&lt;/td&gt;
&lt;/tr&gt;&lt;tr&gt;&lt;td style=&quot;text-align:left;&quot;&gt;University of East London&lt;/td&gt;
&lt;td class=&quot;xl63&quot; style=&quot;text-align:center;&quot;&gt;3,655&lt;/td&gt;
&lt;td class=&quot;xl63&quot; style=&quot;text-align:center;&quot;&gt;4,030&lt;/td&gt;
&lt;td style=&quot;text-align:center;&quot;&gt;−9.3&lt;/td&gt;
&lt;td style=&quot;text-align:center;&quot;&gt;£3,375,000&lt;/td&gt;
&lt;/tr&gt;&lt;tr&gt;&lt;td style=&quot;text-align:left;&quot;&gt;University of Sunderland&lt;/td&gt;
&lt;td class=&quot;xl63&quot; style=&quot;text-align:center;&quot;&gt;2,245&lt;/td&gt;
