;; Query time: 183 msec ;; SERVER: 10.8.0.1#53(10.8.0.1) ;; WHEN: Thu Oct 6 11:56:24 2011 ;; MSG SIZE rcvd: 173
martin@allusion:~&lt;/span&gt;&lt;span class=&quot;nv&quot;&gt;$ &lt;/span&gt;&lt;span class=&quot;sh&quot;&gt;dig nobelprize.org
