&lt;colgroup&gt;
&lt;col width=&quot;206&quot; /&gt;&amp;lt;/col&amp;gt;
&lt;col width=&quot;86&quot; /&gt;&amp;lt;/col&amp;gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td width=&quot;206&quot; height=&quot;17&quot; align=&quot;LEFT&quot;&gt;University of Sussex&lt;/td&gt;
