&lt;td align=&quot;RIGHT&quot;&gt;4&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td height=&quot;17&quot; align=&quot;LEFT&quot;&gt;King&apos;s College London&lt;/td&gt;
